double DistancePointToPlane(const double point[3], const double planePoint[3], const double planeNormal[3])
{
    double delta[3] =
    {
        point[0] - planePoint[0],
        point[1] - planePoint[1],
        point[2] - planePoint[2]
    };
    return std::fabs(Dot3(delta, planeNormal));
}

double DistanceBetweenParallelLines(const double firstPoint[3], const double secondPoint[3], const double axis[3])
{
    double delta[3] =
    {
        secondPoint[0] - firstPoint[0],
        secondPoint[1] - firstPoint[1],
        secondPoint[2] - firstPoint[2]
    };
    const double alongAxis = Dot3(delta, axis);
    double perpendicular[3] =
    {
        delta[0] - axis[0] * alongAxis,
        delta[1] - axis[1] * alongAxis,
        delta[2] - axis[2] * alongAxis
    };
    return std::sqrt(Dot3(perpendicular, perpendicular));
}

bool IsFaceTangentToCylinder(tag_t cylinderFace, tag_t candidateFace)
{
    if (cylinderFace == NULL_TAG || candidateFace == NULL_TAG || cylinderFace == candidateFace)
    {
        return true;
    }

    double cylinderPoint[3] = {0.0, 0.0, 0.0};
    double cylinderAxis[3] = {0.0, 0.0, 0.0};
    double cylinderRadius = 0.0;
    if (!AskCylinderFaceData(cylinderFace, cylinderPoint, cylinderAxis, cylinderRadius))
    {
        return true;
    }

    int candidateType = 0;
    if (!AskFaceType(candidateFace, candidateType))
    {
        DebugLog("    cylinder tangent check failed: cannot read candidate type, cylinder=" +
            FormatTag(cylinderFace) + ", candidate=" + FormatTag(candidateFace));
        return false;
    }

    if (candidateType == UF_MODL_PLANAR_FACE)
    {
        double planePoint[3] = {0.0, 0.0, 0.0};
        double planeNormal[3] = {0.0, 0.0, 0.0};
        if (!AskPlanarFacePlane(candidateFace, planePoint, planeNormal))
        {
            DebugLog("    cylinder tangent check failed: cannot read plane, cylinder=" +
                FormatTag(cylinderFace) + ", candidate=" + FormatTag(candidateFace));
            return false;
        }

        const double axisNormalCos = std::fabs(Dot3(cylinderAxis, planeNormal));
        const double axisPlaneDistance = DistancePointToPlane(cylinderPoint, planePoint, planeNormal);
        const bool tangent = axisNormalCos <= 0.05 &&
            std::fabs(axisPlaneDistance - cylinderRadius) <= kThicknessTolerance;
        DebugLog("    cylinder-plane tangent check: cylinder=" + FormatTag(cylinderFace) +
            ", candidate=" + FormatTag(candidateFace) +
            ", axisNormalCos=" + FormatDouble(axisNormalCos) +
            ", distance=" + FormatDouble(axisPlaneDistance) +
            ", radius=" + FormatDouble(cylinderRadius) +
            ", tangent=" + FormatTag(static_cast<tag_t>(tangent ? 1 : 0)));
        return tangent;
    }

    if (candidateType == UF_MODL_CYLINDRICAL_FACE)
    {
        double otherPoint[3] = {0.0, 0.0, 0.0};
        double otherAxis[3] = {0.0, 0.0, 0.0};
        double otherRadius = 0.0;
        if (!AskCylinderFaceData(candidateFace, otherPoint, otherAxis, otherRadius))
        {
            return false;
        }

        const double axisCos = std::fabs(Dot3(cylinderAxis, otherAxis));
        const double axisDistance = DistanceBetweenParallelLines(cylinderPoint, otherPoint, cylinderAxis);
        const double externalDelta = std::fabs(axisDistance - (cylinderRadius + otherRadius));
        const double internalDelta = std::fabs(axisDistance - std::fabs(cylinderRadius - otherRadius));
        const bool tangent = axisCos >= 0.98 &&
            (externalDelta <= kThicknessTolerance || internalDelta <= kThicknessTolerance);
        DebugLog("    cylinder-cylinder tangent check: cylinder=" + FormatTag(cylinderFace) +
            ", candidate=" + FormatTag(candidateFace) +
            ", axisCos=" + FormatDouble(axisCos) +
            ", axisDistance=" + FormatDouble(axisDistance) +
            ", radius1=" + FormatDouble(cylinderRadius) +
            ", radius2=" + FormatDouble(otherRadius) +
            ", tangent=" + FormatTag(static_cast<tag_t>(tangent ? 1 : 0)));
        return tangent;
    }

    DebugLog("    cylinder tangent check rejected: unsupported candidate type, cylinder=" +
        FormatTag(cylinderFace) +
        ", candidate=" + FormatTag(candidateFace) +
        ", type=" + FormatTag(static_cast<tag_t>(candidateType)));
    return false;
}

bool MustRespectCylinderTangency(
    const std::vector<tag_t>& adjacentFaces,
    tag_t currentFace,
    tag_t candidateFace,
    tag_t& cylinderFace,
    tag_t& tangentFace)
{
    cylinderFace = NULL_TAG;
    tangentFace = candidateFace;

    int currentType = 0;
    if (AskFaceType(currentFace, currentType) && currentType == UF_MODL_CYLINDRICAL_FACE)
    {
        cylinderFace = currentFace;
        tangentFace = candidateFace;
        return true;
    }

    int candidateType = 0;
    if (AskFaceType(candidateFace, candidateType) && candidateType == UF_MODL_CYLINDRICAL_FACE)
    {
        cylinderFace = candidateFace;
        tangentFace = currentFace;
        return true;
    }

    for (std::size_t index = 0; index < adjacentFaces.size(); ++index)
    {
        int faceType = 0;
        if (adjacentFaces[index] != NULL_TAG &&
            AskFaceType(adjacentFaces[index], faceType) &&
            faceType == UF_MODL_CYLINDRICAL_FACE)
        {
            cylinderFace = adjacentFaces[index];
            tangentFace = (adjacentFaces[index] == candidateFace) ? currentFace : candidateFace;
            break;
        }
    }

    return cylinderFace != NULL_TAG;
}

bool IsFaceOnReferencePlane(tag_t faceTag, const double referencePoint[3], const double referenceNormal[3])
{
    double point[3] = {0.0, 0.0, 0.0};
    double normal[3] = {0.0, 0.0, 0.0};
    if (!AskPlanarFacePlane(faceTag, point, normal) ||
        std::fabs(Dot3(referenceNormal, normal)) < 0.999)
    {
        return false;
    }

    double delta[3] =
    {
        point[0] - referencePoint[0],
        point[1] - referencePoint[1],
        point[2] - referencePoint[2]
    };
    return std::fabs(Dot3(delta, referenceNormal)) <= kCoplanarDistanceTolerance;
}

bool IsThicknessFaceByParallelEdgeDistance(tag_t faceTag, tag_t sharedEdgeTag, double thickness)
{
    if (faceTag == NULL_TAG || sharedEdgeTag == NULL_TAG || thickness <= kMinThickness)
    {
        DebugLog("Thickness face check skipped: face=" + FormatTag(faceTag) +
            ", sharedEdge=" + FormatTag(sharedEdgeTag) +
            ", thickness=" + FormatDouble(thickness));
        return false;
    }

    double sharedPoint1[3] = {0.0, 0.0, 0.0};
    double sharedPoint2[3] = {0.0, 0.0, 0.0};
    int sharedVertexCount = 0;
    if (UF_MODL_ask_edge_verts(sharedEdgeTag, sharedPoint1, sharedPoint2, &sharedVertexCount) != 0 ||
        sharedVertexCount != 2)
    {
        DebugLog("Thickness face check failed: cannot read shared edge verts, edge=" + FormatTag(sharedEdgeTag));
        return false;
    }

    double sharedDirection[3] =
    {
        sharedPoint2[0] - sharedPoint1[0],
        sharedPoint2[1] - sharedPoint1[1],
        sharedPoint2[2] - sharedPoint1[2]
    };
    if (!Normalize3(sharedDirection))
    {
        DebugLog("Thickness face check failed: zero shared edge direction, edge=" + FormatTag(sharedEdgeTag));
        return false;
    }

    const std::vector<tag_t> edges = AskFaceEdges(faceTag);
    DebugLog("Thickness face check: face=" + FormatTag(faceTag) +
        ", sharedEdge=" + FormatTag(sharedEdgeTag) +
        ", faceEdges=" + FormatTag(static_cast<tag_t>(edges.size())) +
        ", thickness=" + FormatDouble(thickness));
    int connectedThicknessEdges = 0;
    for (std::size_t index = 0; index < edges.size(); ++index)
    {
        if (edges[index] == sharedEdgeTag)
        {
            continue;
        }

        double point1[3] = {0.0, 0.0, 0.0};
        double point2[3] = {0.0, 0.0, 0.0};
        int vertexCount = 0;
        if (UF_MODL_ask_edge_verts(edges[index], point1, point2, &vertexCount) != 0 || vertexCount != 2)
        {
            DebugLog("  skip edge " + FormatTag(edges[index]) + ": cannot read verts");
            continue;
        }

        const bool connectedToSharedEdge =
            PointsCoincident(point1, sharedPoint1) ||
            PointsCoincident(point1, sharedPoint2) ||
            PointsCoincident(point2, sharedPoint1) ||
            PointsCoincident(point2, sharedPoint2);
        if (connectedToSharedEdge)
        {
            const double connectedLength = Distance3(point1, point2);
            DebugLog("  connected edge " + FormatTag(edges[index]) +
                ": length=" + FormatDouble(connectedLength) +
                ", delta=" + FormatDouble(std::fabs(connectedLength - thickness)));
            if (std::fabs(connectedLength - thickness) <= kThicknessTolerance)
            {
                ++connectedThicknessEdges;
            }
        }

        double edgeDirection[3] =
        {
            point2[0] - point1[0],
            point2[1] - point1[1],
            point2[2] - point1[2]
        };
        if (!Normalize3(edgeDirection) || std::fabs(Dot3(sharedDirection, edgeDirection)) < kParallelCosTolerance)
        {
            DebugLog("  skip edge " + FormatTag(edges[index]) +
                ": not parallel, cos=" + FormatDouble(std::fabs(Dot3(sharedDirection, edgeDirection))));
            continue;
        }

        const double distance = std::min(
            DistancePointToLine3(point1, sharedPoint1, sharedPoint2),
            DistancePointToLine3(point2, sharedPoint1, sharedPoint2));
        DebugLog("  parallel edge " + FormatTag(edges[index]) +
            ": distance=" + FormatDouble(distance) +
            ", delta=" + FormatDouble(std::fabs(distance - thickness)));
        if (std::fabs(distance - thickness) <= kThicknessTolerance)
        {
            DebugLog("  face " + FormatTag(faceTag) + " is thickness/end face");
            return true;
        }
    }

    if (connectedThicknessEdges > 0)
    {
        DebugLog("  face " + FormatTag(faceTag) +
            " is thickness/end face by connected edge length, matchedEdges=" +
            FormatTag(static_cast<tag_t>(connectedThicknessEdges)));
        return true;
    }

    DebugLog("  face " + FormatTag(faceTag) + " is not thickness/end face");
    return false;
}

bool AskSheetThickness(tag_t bodyTag, tag_t selectedFaceTag, const double selectedPoint[3], const double selectedNormal[3], double& thickness, double inwardNormal[3])
{
    thickness = 0.0;
    inwardNormal[0] = selectedNormal[0];
    inwardNormal[1] = selectedNormal[1];
    inwardNormal[2] = selectedNormal[2];
    double selectedArea = 0.0;
    if (!AskPlanarFaceProjectedArea(selectedFaceTag, selectedArea))
    {
        DebugLog("Thickness failed: cannot get selected face area, face=" + FormatTag(selectedFaceTag));
        return false;
    }

    const std::vector<tag_t> bodyFaces = AskBodyFaces(bodyTag);
    DebugLog("Thickness start: body=" + FormatTag(bodyTag) +
        ", selectedFace=" + FormatTag(selectedFaceTag) +
        ", selectedArea=" + FormatDouble(selectedArea) +
        ", bodyFaces=" + FormatTag(static_cast<tag_t>(bodyFaces.size())) +
        ", normal=" + FormatVector3(selectedNormal));
    double bestDistance = DBL_MAX;
    double bestDirection[3] = {selectedNormal[0], selectedNormal[1], selectedNormal[2]};
    for (std::size_t index = 0; index < bodyFaces.size(); ++index)
    {
        if (bodyFaces[index] == selectedFaceTag)
        {
            continue;
        }

        double point[3] = {0.0, 0.0, 0.0};
        double normal[3] = {0.0, 0.0, 0.0};
        if (!AskPlanarFacePlane(bodyFaces[index], point, normal) ||
            std::fabs(Dot3(selectedNormal, normal)) < kParallelCosTolerance)
        {
            DebugLog("  thickness candidate skip face=" + FormatTag(bodyFaces[index]) + ": not planar/parallel");
            continue;
        }

        double area = 0.0;
        if (!AskPlanarFaceProjectedArea(bodyFaces[index], area) || area < selectedArea * 0.5)
        {
            DebugLog("  thickness candidate skip face=" + FormatTag(bodyFaces[index]) +
                ": area=" + FormatDouble(area) +
                ", required>=" + FormatDouble(selectedArea * 0.5));
            continue;
        }

        double delta[3] =
        {
            point[0] - selectedPoint[0],
            point[1] - selectedPoint[1],
            point[2] - selectedPoint[2]
        };
        const double distance = std::fabs(Dot3(delta, selectedNormal));
        double directionSign = Dot3(delta, selectedNormal) >= 0.0 ? 1.0 : -1.0;
        DebugLog("  thickness candidate face=" + FormatTag(bodyFaces[index]) +
            ", area=" + FormatDouble(area) +
            ", distance=" + FormatDouble(distance) +
            ", directionSign=" + FormatDouble(directionSign));
        if (distance > kMinThickness && distance < bestDistance)
        {
            bestDistance = distance;
            bestDirection[0] = selectedNormal[0] * directionSign;
            bestDirection[1] = selectedNormal[1] * directionSign;
            bestDirection[2] = selectedNormal[2] * directionSign;
        }
    }

    if (bestDistance == DBL_MAX)
    {
        DebugLog("Thickness failed: no parallel face candidate");
        return false;
    }

    thickness = bestDistance;
    inwardNormal[0] = bestDirection[0];
    inwardNormal[1] = bestDirection[1];
    inwardNormal[2] = bestDirection[2];
    Normalize3(inwardNormal);
    DebugLog("Thickness result: " + FormatDouble(thickness) +
        ", inwardNormal=" + FormatVector3(inwardNormal));
    return true;
}

bool AskSheetThickness(tag_t bodyTag, tag_t selectedFaceTag, const double selectedPoint[3], const double selectedNormal[3], double& thickness)
{
    double inwardNormal[3] = {0.0, 0.0, 0.0};
    return AskSheetThickness(bodyTag, selectedFaceTag, selectedPoint, selectedNormal, thickness, inwardNormal);
}

std::vector<NXOpen::Face*> CollectFeatureFaces(NXOpen::Features::Feature* feature)
{
    std::vector<NXOpen::Face*> faces;
    if (feature == NULL)
    {
        return faces;
    }

    faces = feature->GetFaces();
    if (!faces.empty())
    {
        return faces;
    }

    const std::vector<NXOpen::Body*> bodies = feature->GetBodies();
    for (std::size_t bodyIndex = 0; bodyIndex < bodies.size(); ++bodyIndex)
    {
        if (bodies[bodyIndex] == NULL)
        {
            continue;
        }

        const std::vector<NXOpen::Face*> bodyFaces = bodies[bodyIndex]->GetFaces();
        faces.insert(faces.end(), bodyFaces.begin(), bodyFaces.end());
    }

    return faces;
}

bool AskReferenceNormal(NXOpen::Face* face, double normal[3])
{
    if (face == NULL)
    {
        return false;
    }

    double point[3] = {0.0, 0.0, 0.0};
    return AskPlanarFacePlane(face->Tag(), point, normal);
}

NXOpen::Features::Feature* ThickenFacesAlongInwardNormal(
    NXOpen::Part* workPart,
    const std::vector<NXOpen::Face*>& faces,
    double thickness,
    const double inwardNormal[3])
{
    if (workPart == NULL || faces.empty() || thickness <= kMinThickness)
    {
        DebugLog("  thicken skipped: invalid input, faces=" +
            FormatTag(static_cast<tag_t>(faces.size())) +
            ", thickness=" + FormatDouble(thickness));
        return NULL;
    }

    NXOpen::Features::ThickenBuilder* builder =
        workPart->Features()->CreateThickenBuilder(NULL);
    if (builder == NULL)
    {
        DebugLog("  thicken failed: null builder");
        return NULL;
    }

    try
    {
        std::vector<NXOpen::SelectionIntentRule*> rules;
        rules.push_back(workPart->ScRuleFactory()->CreateRuleFaceDumb(faces));
        builder->FaceCollector()->ReplaceRules(rules, false);
        builder->FirstOffset()->SetFormula(FormatDouble(thickness).c_str());
        builder->SecondOffset()->SetFormula("0");
        builder->BooleanOperation()->SetType(
            NXOpen::GeometricUtilities::BooleanOperation::BooleanTypeCreate);
        builder->SetTolerance(0.01);

        double extractedNormal[3] = {0.0, 0.0, 0.0};
        bool reverseDirection = false;
        bool hasDirectionReference = false;
        for (std::size_t index = 0; index < faces.size(); ++index)
        {
            if (AskReferenceNormal(faces[index], extractedNormal) &&
                std::fabs(Dot3(extractedNormal, inwardNormal)) > kParallelCosTolerance)
            {
                hasDirectionReference = true;
                break;
            }
        }

        if (hasDirectionReference)
        {
            reverseDirection = Dot3(extractedNormal, inwardNormal) < 0.0;
            DebugLog("  thicken direction check: extractedNormal=" +
                FormatVector3(extractedNormal) +
                ", inwardNormal=" + FormatVector3(inwardNormal) +
                ", reverse=" + FormatTag(static_cast<tag_t>(reverseDirection ? 1 : 0)));
        }
        else
        {
            DebugLog("  thicken direction check skipped: cannot find parallel extracted face normal");
        }
        builder->SetReverseDirection(reverseDirection);

        NXOpen::Features::Feature* feature = builder->CommitFeature();
        if (feature != NULL)
        {
            DebugLog("  thicken feature ok: feature=" + FormatTag(feature->Tag()) +
                ", faces=" + FormatTag(static_cast<tag_t>(faces.size())) +
                ", thickness=" + FormatDouble(thickness));
        }
        else
        {
            DebugLog("  thicken feature returned null");
        }
        builder->Destroy();
        return feature;
    }
    catch (...)
    {
        builder->Destroy();
        DebugLog("  thicken feature exception");
        throw;
    }
}

std::vector<tag_t> BuildSelectedFaceChain(tag_t bodyTag, tag_t selectedFaceTag, double thickness)
{
    std::vector<tag_t> chain;
    double selectedPoint[3] = {0.0, 0.0, 0.0};
    double selectedNormal[3] = {0.0, 0.0, 0.0};
    if (!AskPlanarFacePlane(selectedFaceTag, selectedPoint, selectedNormal))
    {
        DebugLog("Face chain failed: selected face is not planar, face=" + FormatTag(selectedFaceTag));
        return chain;
    }

    DebugLog("Face chain start: selectedFace=" + FormatTag(selectedFaceTag) +
        ", body=" + FormatTag(bodyTag) +
        ", thickness=" + FormatDouble(thickness) +
        ", basePoint=" + FormatVector3(selectedPoint) +
        ", baseNormal=" + FormatVector3(selectedNormal));

    std::set<tag_t> visited;
    std::deque<tag_t> pending;
    visited.insert(selectedFaceTag);
    pending.push_back(selectedFaceTag);

    while (!pending.empty())
    {
        const tag_t currentFace = pending.front();
        pending.pop_front();
        chain.push_back(currentFace);
        DebugLog("Chain visit face=" + FormatTag(currentFace));

        const std::vector<tag_t> edges = AskFaceEdges(currentFace);
        DebugLog("  face edges count=" + FormatTag(static_cast<tag_t>(edges.size())));
        for (std::size_t edgeIndex = 0; edgeIndex < edges.size(); ++edgeIndex)
        {
            const std::vector<tag_t> adjacentFaces = AskEdgeAdjacentFaces(edges[edgeIndex]);
            DebugLog("  edge=" + FormatTag(edges[edgeIndex]) +
                ", adjacentFaces=" + FormatTag(static_cast<tag_t>(adjacentFaces.size())));
            for (std::size_t faceIndex = 0; faceIndex < adjacentFaces.size(); ++faceIndex)
            {
                const tag_t adjacentFace = adjacentFaces[faceIndex];
                if (adjacentFace == NULL_TAG || visited.find(adjacentFace) != visited.end())
                {
                    DebugLog("    adjacent skip face=" + FormatTag(adjacentFace) + ": null/visited");
                    continue;
                }

                tag_t adjacentBody = NULL_TAG;
                if (UF_MODL_ask_face_body(adjacentFace, &adjacentBody) != 0 || adjacentBody != bodyTag)
                {
                    DebugLog("    adjacent skip face=" + FormatTag(adjacentFace) +
                        ": different body=" + FormatTag(adjacentBody));
                    continue;
                }

                tag_t cylinderFace = NULL_TAG;
                tag_t tangentFace = NULL_TAG;
                if (MustRespectCylinderTangency(adjacentFaces, currentFace, adjacentFace, cylinderFace, tangentFace))
                {
                    if (IsFaceTangentToCylinder(cylinderFace, tangentFace))
                    {
                        DebugLog("    adjacent add by cylinder tangent bypass: candidate=" +
                            FormatTag(adjacentFace) +
                            ", cylinder=" + FormatTag(cylinderFace) +
                            ", tangentFace=" + FormatTag(tangentFace));
                        visited.insert(adjacentFace);
                        pending.push_back(adjacentFace);
                        continue;
                    }

                    DebugLog("    adjacent excluded: not tangent to cylinder, cylinder=" +
                        FormatTag(cylinderFace) +
                        ", tangentFace=" + FormatTag(tangentFace) +
                        ", candidate=" + FormatTag(adjacentFace));
                    visited.insert(adjacentFace);
                    continue;
                }

                if (IsThicknessFaceByParallelEdgeDistance(adjacentFace, edges[edgeIndex], thickness))
                {
                    DebugLog("    adjacent excluded end face=" + FormatTag(adjacentFace));
                    visited.insert(adjacentFace);
                    continue;
                }

                DebugLog("    adjacent add face=" + FormatTag(adjacentFace));
                visited.insert(adjacentFace);
                pending.push_back(adjacentFace);
            }
        }
    }

    DebugLog("Face chain result count=" + FormatTag(static_cast<tag_t>(chain.size())));
    return chain;
}

